import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Test scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"archive/local-trend-upgrades/trend-graph-ui/test.md","filePath":"archive/local-trend-upgrades/trend-graph-ui/test.md"}'),n={name:"archive/local-trend-upgrades/trend-graph-ui/test.md"};function o(s,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="test-scenarios" tabindex="-1">Test scenarios <a class="header-anchor" href="#test-scenarios" aria-label="Permalink to &quot;Test scenarios&quot;">​</a></h1><ul><li>Query defaults: all dates, page 20, depth 2, maxNodes 100. Submit search/date resets page; paging doesn&#39;t unexpectedly clear selected Trend. Malformed URL stays safe and offers reset. Deep link selects without searching first.</li><li>Correct search/query forwarding and no prior graph visible during new selection; network cancellation / delayed results cannot show a mismatched graph.</li><li>Root-only and connected graph, parallel/directed edges, valid properties, rejected dangling edges/oversized malformed payloads. Truncation warning with exact server reason. Unsafe URLs remain text and HTML content remains escaped.</li><li>Node/edge selection via canvas and lists; zoom, fit, pan buttons, pointer pan; reset view and state on new graph, no viewport state leakage between roots.</li><li>Empty search, 404 missing root, 503, retry, pending/loading and successful reload; list failure doesn&#39;t hide a deep-linked graph. No production fallback fixtures.</li><li>Keyboard focus and labels, language switch, light/dark screenshots, narrow screen no horizontal overflow, reduced motion and no animation dependency.</li><li>Build and changed-file lint; local artifacts only in ignored keep-local-only.</li></ul><h2 id="results-2026-10-25" tabindex="-1">Results (2026-10-25) <a class="header-anchor" href="#results-2026-10-25" aria-label="Permalink to &quot;Results (2026-10-25)&quot;">​</a></h2><ul><li>Production build PASS; new graph view is lazy loaded. Existing application large-chunk and mixed static/dynamic library import warnings remain unchanged.</li><li>Targeted ESLint PASS with no new warnings; Admin index remains 140 lines and all new source files are below 300 lines. 52 graph locale keys match in vi/en.</li><li>Playwright CLI on a separate Vite 3107 instance, actual AdminPage rendered under BrowserRouter with API fixtures: PASS, 18 intercepted graph/search requests and zero application pageerror events. No DB writes or paid model calls.</li><li>PASS: default all dates, literal Vietnamese/ampersand/plus/percent query, search submit/re-submit, pagination, selected root and depth changes, no previous root while pending, history Back/Forward, viewport reset on root change, deep link still works when search fails or does not contain the selected root.</li><li>PASS: zoom, fit-to-content, directional and pointer pan, keyboard node selection, relationship list filtering/selection and property projection. 4 fixture nodes / 5 distinct curved paths; invalid dangling/duplicate topology rejected by schema.</li><li>PASS: isolated root, 404, 503, malformed graph, retry, truncation reason, empty search, independent search error, invalid URL/reset. React escapes hostile text; javascript source URL is not rendered as a link.</li><li>PASS: 375/768/1440 x light/dark = 6 layouts with no horizontal page overflow. SVG text measured approximately 14 CSS px in every case; vi/en and reduced motion checked. Light/dark screenshots visually reviewed under output/playwright.</li><li>Local-only QA script is in ignored keep-local-only; screenshots and CLI logs are ignored. No tests added under src, no package/dependency changes or commits.</li></ul><p>Live authenticated Gateway -&gt; Business -&gt; AI -&gt; Neo4j has not been exercised in this UI phase. Backend direct read checks are documented in trend-graph-core. The synthetic browser fixture can produce Vite HMR local-network WebSocket errors; these concern development hot reload in that test context, not application graph requests. Application error cases intentionally produce HTTP 404/503 in QA.</p><h2 id="commit-preflight-2026-10-26" tabindex="-1">Commit preflight (2026-10-26) <a class="header-anchor" href="#commit-preflight-2026-10-26" aria-label="Permalink to &quot;Commit preflight (2026-10-26)&quot;">​</a></h2><p>The UI has since gained force/radial layouts, node expansion, drag/pin and label controls. The results above describe the original foundation, not a full browser regression of these later additions. The exact staged tree passed production build and changed-file ESLint in an isolated local checkout without replay-only files. No new dependency, test code, image, environment file or local tool is included in the commit. Some later UI components exceed the suggested 300-line size; component decomposition is deferred rather than mixed into this commit.</p><h2 id="graph-first-revision-—-2026-11-22" tabindex="-1">Graph-first revision — 2026-11-22 <a class="header-anchor" href="#graph-first-revision-—-2026-11-22" aria-label="Permalink to &quot;Graph-first revision — 2026-11-22&quot;">​</a></h2><p>Verify default overview root/topology loads automatically, scans disconnected components and can pause/resume. Default posts/incident edges hidden and can be restored, root remains top1. Filters and details closed initially; open/close/Escape and click node/edge work without resetting camera or reload. Hover node/edge for 650ms shows properties, pointer leave/drag/zoom cancels stale preview, hover never opens inspector. Types use shape/color/legend; edges directed/labeled, no fabricated links. Deep link still loads selected trend. Verify keyboard lists, vi/en, light/dark, 375/768/1440 and npm run ci.</p><p>Browser fixture verification PASS: default overview auto-scans both connected/disconnected components (8 loaded, 7 displayed because post hidden); restoring posts shows 8. Filter toggle preserves API call count. Delayed node and edge hover, edge click inspector, close/Escape, keyboard node selection, pause/resume, explicit trend deep link PASS. 375/768/1440 no horizontal page overflow; vi/en and light/dark inspected. Root/adjacent layout and camera resize adjusted after visual review. Fixture and screenshots remain local-only; no DB writes, model calls or production changes.</p><p>Final npm run ci PASS (exit 0): ESLint 0 errors with 227 existing warnings, app/node TypeScript, editor build, app production build and 105-page prerender. Browser fixture suite PASS including keyboard selection and pause/resume. Dev server localhost:3000 returns updated graph-first module (HTTP 200). Build-generated unrelated tracked SEO files restored; existing vendor/font-urls change preserved. No commit/push performed.</p>',11)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
